//! SP00-W04 contract: determinism, isolation, mutations, and path safety.
//! These checks read generated bytes. They do not re-call the row writers to grade them.

use std::fs::{self, File};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use oo_datagen::csvfile::for_each_row;
use oo_datagen::digest::{hash_file, sha256_hex, tree_preimage};
use oo_datagen::facts::{SMELLS, TRUTH_MARKER};
use oo_datagen::pathsafety::{Exists, STAGE_MARK, remove_owned_stage, validate_rel};
use oo_datagen::plan::{Scale, SmellSet};
use oo_datagen::{Options, cli, export_sources, generate, verify_dataset};

struct Scratch(PathBuf);

impl Scratch {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("oo-datagen-sp00-{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&path);
        fs::create_dir(&path).expect("scratch");
        Self(path)
    }

    fn path(&self) -> &Path {
        &self.0
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn lock() -> std::sync::MutexGuard<'static, ()> {
    static LOCK: Mutex<()> = Mutex::new(());
    LOCK.lock().expect("lock")
}

fn opts(scale: Scale, seed: u64, output: &Path, scope: &Path) -> Options {
    Options {
        scale,
        seed,
        output: output.to_path_buf(),
        scope: scope.to_path_buf(),
        exists: Exists::Fail,
        smells: SmellSet::all_on(),
        stop_after_files: None,
    }
}

fn rows(path: &Path) -> u64 {
    for_each_row(File::open(path).expect("csv"), |_| Ok(()))
        .expect("scan")
        .rows
}

fn manifest(root: &Path) -> String {
    fs::read_to_string(root.join("dataset-manifest.json")).expect("manifest")
}

fn reseal(root: &Path, text: &str) {
    let bytes = text.as_bytes();
    fs::write(root.join("dataset-manifest.json"), bytes).unwrap();
    let side = format!("{}\n", sha256_hex(bytes));
    fs::write(root.join("dataset-manifest.sha256"), side).unwrap();
}

fn copy_tree(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for entry in fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let dest = to.join(entry.file_name());
        let meta = fs::symlink_metadata(entry.path()).unwrap();
        if meta.is_dir() {
            copy_tree(&entry.path(), &dest);
        } else if meta.is_file() {
            fs::copy(entry.path(), &dest).unwrap();
        } else {
            panic!("unexpected file type in dataset copy");
        }
    }
}

fn replace_once(text: &str, from: &str, to: &str) -> String {
    assert_eq!(text.matches(from).count(), 1, "needle {from} is not unique");
    text.replace(from, to)
}

fn tree_with_override(root: &Path, path: &str, digest: &str) -> String {
    let mut entries = Vec::new();
    fn walk(
        dir: &Path,
        prefix: &str,
        path: &str,
        digest: &str,
        entries: &mut Vec<(String, u64, String)>,
    ) {
        for entry in fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            let name = entry.file_name();
            let name = name.to_str().unwrap();
            let rel = if prefix.is_empty() {
                name.to_string()
            } else {
                format!("{prefix}/{name}")
            };
            let meta = fs::symlink_metadata(entry.path()).unwrap();
            if meta.is_dir() {
                walk(&entry.path(), &rel, path, digest, entries);
            } else if meta.is_file()
                && rel != "dataset-manifest.json"
                && rel != "dataset-manifest.sha256"
            {
                let (len, hashed) = hash_file(&entry.path()).unwrap();
                let digest = if rel == path {
                    digest.to_string()
                } else {
                    hashed
                };
                entries.push((rel, len, digest));
            }
        }
    }
    walk(root, "", path, digest, &mut entries);
    entries.sort_by(|left, right| left.0.cmp(&right.0));
    tree_preimage(&entries)
}

fn set_tree(text: &str, tree: &str) -> String {
    let key = "\"tree_sha256\":\"";
    let start = text.find(key).expect("tree") + key.len();
    let end = start + 64;
    assert!(text[start..end].chars().all(|ch| ch.is_ascii_hexdigit()));
    let mut out = text.to_string();
    out.replace_range(start..end, tree);
    out
}

#[test]
fn sp00_xs_contract() {
    let _guard = lock();
    let scratch = Scratch::new("xs");
    let scope = scratch.path().to_path_buf();
    path_and_cli(&scope);
    scales_and_cancel(&scope);

    let first = scope.join("xs-a");
    let second = scope.join("xs-b");
    let other = scope.join("xs-c");
    let left = generate(&opts(Scale::Xs, 1, &first, &scope)).expect("xs seed 1");
    let right = generate(&opts(Scale::Xs, 1, &second, &scope)).expect("xs seed 1 again");
    assert_eq!(left.tree_sha256, right.tree_sha256);
    assert_eq!(manifest(&first), manifest(&second));
    assert_eq!(left.partition, 0x910a);
    let verified = verify_dataset(&first).expect("verify xs");
    assert_eq!(verified.tree_sha256, left.tree_sha256);
    assert_eq!(
        rows(&first.join("source-inputs/mysql-erp/tables/kh.csv")),
        200
    );
    assert_eq!(
        rows(&first.join("source-inputs/mysql-erp/tables/dd.csv")),
        2_000
    );
    assert!(rows(&first.join("source-inputs/postgres-tms/shards/gj_202601.csv")) > 1_000);
    assert_eq!(
        rows(&first.join("source-inputs/postgres-tms/tables/xl.csv")),
        24
    );
    let kh = fs::read(first.join("source-inputs/mysql-erp/tables/kh.csv")).unwrap();
    assert!(std::str::from_utf8(&kh).unwrap().contains("10.50"));
    assert!(std::str::from_utf8(&kh).unwrap().contains("K910A"));

    let alt = generate(&opts(Scale::Xs, 2, &other, &scope)).expect("xs seed 2");
    assert_ne!(alt.tree_sha256, left.tree_sha256);
    assert_eq!(alt.partition, 0x9758);
    let alt_kh = fs::read_to_string(other.join("source-inputs/mysql-erp/tables/kh.csv")).unwrap();
    assert!(alt_kh.contains("K9758"));
    assert!(!alt_kh.contains("K910A"));

    let gbk_fix =
        fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/gbk-huanxiong.bin")).unwrap();
    let rare_fix =
        fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/gb18030-rare.bin")).unwrap();
    let gbk = fs::read(first.join("source-inputs/encoding/legacy-gbk.bin")).unwrap();
    let rare = fs::read(first.join("source-inputs/encoding/legacy-gb18030.bin")).unwrap();
    assert_eq!(gbk, gbk_fix);
    assert_eq!(rare, rare_fix);
    assert!(std::str::from_utf8(&gbk).is_err());
    assert!(std::str::from_utf8(&rare).is_err());
    let untrusted = fs::read_to_string(first.join("source-inputs/comments/untrusted.sql")).unwrap();
    assert!(untrusted.contains("a''b"));
    assert!(untrusted.contains("OO-CANARY-PROMPT-7F3A"));
    let mysql = fs::read_to_string(first.join("source-inputs/mysql-erp/ddl.sql")).unwrap();
    let pg = fs::read_to_string(first.join("source-inputs/postgres-tms/ddl.sql")).unwrap();
    assert!(!oo_datagen::ddl::ddl_has_foreign_key(&mysql));
    assert!(!oo_datagen::ddl::ddl_has_foreign_key(&pg));
    assert!(pg.contains("gj_202611"));
    assert!(
        !fs::read_to_string(first.join("attacks/sql.json"))
            .unwrap()
            .contains("model_verdict")
    );
    assert!(
        fs::read_to_string(first.join("hidden-truth/README.txt"))
            .unwrap()
            .contains(TRUTH_MARKER)
    );

    mutations(&scope, &first);
    export_hides_truth(&scope, &first);
    smell_off(&scope);
    exists_modes(&scope, &first);
}

fn path_and_cli(scope: &Path) {
    assert!(cli::version_text().contains("oo-datagen/v2"));
    assert!(cli::version_text().contains("canonical-value/v1"));
    assert!(cli::version_text().contains("oo-splitmix64/v1"));
    assert!(cli::version_text().contains("type-policy/v1"));
    assert_eq!(cli::run(["help"]).unwrap(), 0);
    assert_eq!(cli::run(["help", "extra"]).unwrap(), 2);
    assert_eq!(cli::run(["version", "extra"]).unwrap(), 2);
    assert_eq!(cli::run(["generate", "--scale", "xs"]).unwrap(), 2);
    assert_eq!(cli::run(["generate"]).unwrap(), 2);
    let scope_s = scope.to_str().expect("scope utf-8");
    let positional = cli::run([
        "generate",
        "--scale",
        "xs",
        "--seed",
        "1",
        "--output",
        "positional-ok",
        "--scope",
        scope_s,
        "IGNORED",
    ])
    .unwrap_err();
    assert!(
        positional.to_string().contains("unsupported positional"),
        "{positional}"
    );
    assert!(!scope.join("positional-ok").exists());
    let repeated = cli::run([
        "generate", "--scale", "xs", "--seed", "1", "--seed", "2", "--output", "dup-seed",
        "--scope", scope_s,
    ])
    .unwrap_err();
    assert!(
        repeated.to_string().contains("repeated --seed"),
        "{repeated}"
    );
    let unknown = cli::run(["verify", "--dataset", "x", "--bogus"]).unwrap_err();
    assert!(
        unknown.to_string().contains("unknown argument --bogus"),
        "{unknown}"
    );
    let missing_name = verify_dataset(Path::new("bad\nname")).unwrap_err();
    assert!(
        missing_name.to_string().contains("ascii control"),
        "{missing_name}"
    );
    assert!(
        cli::run([
            "generate", "--scale", "xs", "--seed", "nope", "--output", "out"
        ])
        .is_err()
    );

    for bad in [
        "../x",
        "/abs",
        "a/../../b",
        "a\\b",
        "",
        "a/./b",
        "a//b",
        "a/\u{0}b",
    ] {
        assert!(validate_rel(bad).is_err(), "{bad}");
    }
    assert!(validate_rel("source-inputs/mysql-erp/tables/kh.csv").is_ok());

    let secret = scope.join("secret");
    let err = generate(&opts(Scale::Xs, 1, &secret, scope)).unwrap_err();
    assert!(err.to_string().contains("secret"), "{err}");
    let customer = scope.join("customer");
    let err = generate(&opts(Scale::Xs, 1, &customer, scope)).unwrap_err();
    assert!(err.to_string().contains("component customer"), "{err}");
    assert!(!customer.exists());
    let newline = scope.join("bad\nname");
    let err = generate(&opts(Scale::Xs, 1, &newline, scope)).unwrap_err();
    assert!(err.to_string().contains("ascii control"), "{err}");
    assert!(!newline.exists());
    let ssh = scope.join(".ssh");
    let err = generate(&opts(Scale::Xs, 1, &ssh, scope)).unwrap_err();
    assert!(
        err.to_string().contains("explicit") || err.to_string().contains("private"),
        "{err}"
    );
    let nested = scope.join("customer-data").join("out");
    let err = generate(&opts(Scale::Xs, 1, &nested, scope)).unwrap_err();
    assert!(
        err.to_string().contains("customer-data") || err.to_string().contains("private"),
        "{err}"
    );
    let up = scope.join("..").join("oo-datagen-escape");
    let err = generate(&Options {
        output: up,
        ..opts(Scale::Xs, 1, &scope.join("unused"), scope)
    })
    .unwrap_err();
    assert!(err.to_string().contains(".."), "{err}");

    let outside = std::env::temp_dir().join(format!("oo-datagen-outside-{}", std::process::id()));
    let _ = fs::create_dir(&outside);
    let err = generate(&opts(Scale::Xs, 1, &outside.join("child"), scope)).unwrap_err();
    assert!(err.to_string().contains("escapes"), "{err}");
    let _ = fs::remove_dir(&outside);

    let kept = scope.join("kept");
    fs::create_dir(&kept).unwrap();
    fs::write(kept.join("keep.txt"), b"keep").unwrap();
    let err = generate(&opts(Scale::Xs, 1, &kept, scope)).unwrap_err();
    assert!(err.to_string().contains("destination exists"), "{err}");
    assert_eq!(fs::read(kept.join("keep.txt")).unwrap(), b"keep");

    let link = scope.join("linked");
    std::os::unix::fs::symlink(&kept, &link).unwrap();
    let err = generate(&opts(Scale::Xs, 1, &link, scope)).unwrap_err();
    assert!(err.to_string().contains("symlink"), "{err}");
    assert_eq!(fs::read(kept.join("keep.txt")).unwrap(), b"keep");

    stage_does_not_follow(scope);
}

fn stage_does_not_follow(scope: &Path) {
    let canary_dir = scope.join("canary-dir");
    fs::create_dir(&canary_dir).unwrap();
    let canary = canary_dir.join("keep.txt");
    fs::write(&canary, b"keep").unwrap();
    let stage_link = scope.join(".linked.oo-datagen-stage");
    std::os::unix::fs::symlink(&canary_dir, &stage_link).unwrap();
    let mark = scope.join(".linked.oo-datagen-stage-mark");
    fs::write(&mark, STAGE_MARK).unwrap();
    let err = remove_owned_stage(&stage_link, &mark).unwrap_err();
    assert!(err.to_string().contains("not a real directory"), "{err}");
    assert_eq!(fs::read(&canary).unwrap(), b"keep");

    let stage = scope.join(".real.oo-datagen-stage");
    fs::create_dir(&stage).unwrap();
    fs::write(stage.join("keep.txt"), b"keep").unwrap();
    let bad_mark = scope.join(".real.oo-datagen-stage-mark");
    fs::write(&bad_mark, b"not-our-mark\n").unwrap();
    let err = remove_owned_stage(&stage, &bad_mark).unwrap_err();
    assert!(err.to_string().contains("without our mark"), "{err}");
    assert_eq!(fs::read(stage.join("keep.txt")).unwrap(), b"keep");

    fs::write(&bad_mark, STAGE_MARK).unwrap();
    std::os::unix::fs::symlink(&canary, stage.join("link")).unwrap();
    remove_owned_stage(&stage, &bad_mark).unwrap();
    assert_eq!(fs::read(&canary).unwrap(), b"keep");
    assert!(!stage.exists());

    let occupied = scope.join(".occupied.oo-datagen-stage");
    fs::create_dir(&occupied).unwrap();
    fs::write(occupied.join("keep.txt"), b"keep").unwrap();
    let err = generate(&opts(Scale::Xs, 1, &scope.join("occupied"), scope)).unwrap_err();
    assert!(err.to_string().contains("stage already exists"), "{err}");
    assert_eq!(fs::read(occupied.join("keep.txt")).unwrap(), b"keep");
}

fn scales_and_cancel(scope: &Path) {
    let missing = scope.join("no-such-parent");
    for scale in [Scale::M, Scale::L] {
        let err = generate(&opts(scale, 1, &missing.join("out"), scope)).unwrap_err();
        assert!(err.to_string().contains("SP12"), "{err}");
        assert!(!missing.exists());
    }
    for (name, stop) in [("stop0", Some(0)), ("stop1", Some(1))] {
        let output = scope.join(name);
        let err = generate(&Options {
            stop_after_files: stop,
            ..opts(Scale::Xs, 1, &output, scope)
        })
        .unwrap_err();
        assert!(err.to_string().contains("injected stop"), "{err}");
        let parent = fs::canonicalize(scope).unwrap();
        assert!(!output.exists());
        assert!(!parent.join(format!(".{name}.oo-datagen-stage")).exists());
        assert!(
            !parent
                .join(format!(".{name}.oo-datagen-stage-mark"))
                .exists()
        );
    }
}

fn mutations(scope: &Path, src: &Path) {
    let missing = scope.join("mut-missing");
    copy_tree(src, &missing);
    fs::remove_file(missing.join("source-inputs/mysql-erp/tables/kh.csv")).unwrap();
    let err = verify_dataset(&missing).unwrap_err();
    assert!(err.to_string().contains("missing"), "{err}");

    let flipped = scope.join("mut-flip");
    copy_tree(src, &flipped);
    let readme = flipped.join("source-inputs/README.txt");
    let mut bytes = fs::read(&readme).unwrap();
    bytes[0] = b'X';
    fs::write(&readme, bytes).unwrap();
    let err = verify_dataset(&flipped).unwrap_err();
    assert!(err.to_string().contains("hash"), "{err}");

    let counted = scope.join("mut-count");
    copy_tree(src, &counted);
    let text = replace_once(
        &manifest(&counted),
        "\"customers\":200,",
        "\"customers\":201,",
    );
    reseal(&counted, &text);
    let err = verify_dataset(&counted).unwrap_err();
    assert!(err.to_string().contains("row count"), "{err}");
    assert!(err.to_string().contains("customers"), "{err}");

    let hashed = scope.join("mut-hash");
    copy_tree(src, &hashed);
    let rel = "source-inputs/README.txt";
    let (_len, digest) = hash_file(&hashed.join(rel)).unwrap();
    let flipped_digest = flip_hex(&digest);
    let text = replace_once(&manifest(&hashed), &digest, &flipped_digest);
    let text = set_tree(&text, &tree_with_override(&hashed, rel, &flipped_digest));
    reseal(&hashed, &text);
    let err = verify_dataset(&hashed).unwrap_err();
    assert!(err.to_string().contains("hash"), "{err}");

    let visible = scope.join("mut-vis");
    copy_tree(src, &visible);
    let text = manifest(&visible);
    let needle = "\"path\":\"hidden-truth/README.txt\"";
    let pos = text.find(needle).unwrap();
    let end = pos + text[pos..].find('}').unwrap();
    let window = text[pos..end].replacen(
        "\"visibility\":\"hidden-truth\"",
        "\"visibility\":\"source-input\"",
        1,
    );
    assert_ne!(window, &text[pos..end]);
    let mut updated = text.clone();
    updated.replace_range(pos..end, &window);
    reseal(&visible, &updated);
    let err = verify_dataset(&visible).unwrap_err();
    assert!(err.to_string().contains("visibility"), "{err}");

    let leaked = scope.join("mut-leak");
    copy_tree(src, &leaked);
    let mut readme = fs::read_to_string(leaked.join("source-inputs/README.txt")).unwrap();
    readme.push_str(TRUTH_MARKER);
    fs::write(leaked.join("source-inputs/README.txt"), readme).unwrap();
    let err = verify_dataset(&leaked).unwrap_err();
    assert!(err.to_string().contains("leaks"), "{err}");
}

fn flip_hex(digest: &str) -> String {
    let mut chars: Vec<char> = digest.chars().collect();
    let last = chars.last_mut().unwrap();
    *last = if *last == '0' { '1' } else { '0' };
    chars.into_iter().collect()
}

fn export_hides_truth(scope: &Path, dataset: &Path) {
    let out = scope.join("export");
    export_sources(dataset, &out, scope).expect("export");
    assert!(out.join("source-inputs/mysql-erp/tables/kh.csv").is_file());
    assert!(out.join("source-inputs/encoding/legacy-gbk.bin").is_file());
    let consumer = fs::read_to_string(out.join("consumer-manifest.json")).unwrap();
    assert!(!consumer.contains("hidden-truth"));
    assert!(!consumer.contains(TRUTH_MARKER));
    assert!(!consumer.contains("do_not_merge"));
    walk_no_truth(&out);
    let err = verify_dataset(&out).unwrap_err();
    assert!(
        err.to_string().contains("truth counts are missing"),
        "{err}"
    );
}

fn walk_no_truth(dir: &Path) {
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name();
        let name = name.to_str().unwrap();
        assert!(!name.contains("hidden-truth"), "{name}");
        let meta = fs::symlink_metadata(entry.path()).unwrap();
        if meta.is_dir() {
            walk_no_truth(&entry.path());
        } else {
            let bytes = fs::read(entry.path()).unwrap();
            let marker = TRUTH_MARKER.as_bytes();
            assert!(!bytes.windows(marker.len()).any(|window| window == marker));
            assert!(
                !bytes
                    .windows(b"do_not_merge".len())
                    .any(|window| window == b"do_not_merge")
            );
        }
    }
}

fn smell_off(scope: &Path) {
    let output = scope.join("xs-off");
    let mut options = opts(Scale::Xs, 1, &output, scope);
    options.smells = SmellSet::parse_off(&[
        "dst_overlap".to_string(),
        "alias_duplicate_customer".to_string(),
    ])
    .unwrap();
    generate(&options).expect("smell off");
    verify_dataset(&output).expect("verify smell off");
    assert!(
        !output
            .join("source-inputs/postgres-tms/shards/gj_202611.csv")
            .exists()
    );
    assert!(
        !fs::read_to_string(output.join("source-inputs/postgres-tms/ddl.sql"))
            .unwrap()
            .contains("gj_202611")
    );
    let customers = rows(&output.join("source-inputs/mysql-erp/tables/kh.csv"));
    let aliases = rows(&output.join("source-inputs/mysql-erp/tables/kh_bm.csv"));
    assert_eq!(customers, 200);
    assert_eq!(aliases, customers);
}

fn exists_modes(scope: &Path, dataset: &Path) {
    let before = fs::read(dataset.join("dataset-manifest.json")).unwrap();
    let report = generate(&Options {
        exists: Exists::Check,
        ..opts(Scale::Xs, 1, dataset, scope)
    })
    .expect("check");
    assert_eq!(
        fs::read(dataset.join("dataset-manifest.json")).unwrap(),
        before
    );
    assert_eq!(
        report.tree_sha256,
        verify_dataset(dataset).unwrap().tree_sha256
    );
    let err = generate(&Options {
        exists: Exists::Fail,
        ..opts(Scale::Xs, 1, dataset, scope)
    })
    .unwrap_err();
    assert!(err.to_string().contains("destination exists"), "{err}");
    assert_eq!(
        fs::read(dataset.join("dataset-manifest.json")).unwrap(),
        before
    );
    let err = generate(&Options {
        exists: Exists::Resume,
        ..opts(Scale::Xs, 1, dataset, scope)
    })
    .unwrap_err();
    assert!(err.to_string().contains("destination exists"), "{err}");
    assert_eq!(
        fs::read(dataset.join("dataset-manifest.json")).unwrap(),
        before
    );
    let absent = scope.join("check-missing");
    let err = generate(&Options {
        exists: Exists::Check,
        ..opts(Scale::Xs, 1, &absent, scope)
    })
    .unwrap_err();
    assert!(
        err.to_string()
            .contains("check requires an existing dataset"),
        "{err}"
    );
}

#[test]
fn sp00_s_twice() {
    let _guard = lock();
    let scratch = Scratch::new("s");
    let scope = scratch.path().to_path_buf();
    let first = scope.join("s-a");
    let second = scope.join("s-b");
    let left = generate(&opts(Scale::S, 7, &first, &scope)).expect("s");
    let right = generate(&opts(Scale::S, 7, &second, &scope)).expect("s again");
    assert_eq!(left.tree_sha256, right.tree_sha256);
    assert_eq!(manifest(&first), manifest(&second));
    let verified = verify_dataset(&first).expect("verify s");
    assert_eq!(verified.tree_sha256, left.tree_sha256);
    assert_eq!(
        rows(&first.join("source-inputs/mysql-erp/tables/kh.csv")),
        2_000
    );
    let mut track = 0u64;
    for entry in fs::read_dir(first.join("source-inputs/postgres-tms/shards")).unwrap() {
        let entry = entry.unwrap();
        track += rows(&entry.path());
    }
    assert_eq!(track, 100_000);
    assert_eq!(
        rows(&first.join("source-inputs/workload/txn_log.csv")),
        91_000
    );
}

#[test]
fn carrier_flags_keys_and_ddl() {
    let _guard = lock();
    let scratch = Scratch::new("flags");
    let scope = scratch.path().to_path_buf();
    let real = scope.join("real-scope");
    fs::create_dir(&real).unwrap();
    let link = scope.join("link-scope");
    std::os::unix::fs::symlink(&real, &link).unwrap();
    let on = link.join("on");
    generate(&opts(Scale::Xs, 11, &on, &link)).expect("symlink scope");
    verify_dataset(&on).expect("verify on");
    assert!(real.join("on").is_dir());
    assert!(manifest(&on).contains("\"protocol\":\"oo-datagen/v2\""));
    let export_err = export_sources(&on, &scope.join("customer"), &scope).unwrap_err();
    assert!(
        export_err.to_string().contains("component customer"),
        "{export_err}"
    );
    assert!(!scope.join("customer").exists());

    let cents = generate_off(&scope, "off-cents", &["cents"]);
    let fiscal = generate_off(&scope, "off-fiscal", &["fiscal_calendar"]);
    let closing = generate_off(&scope, "off-closing", &["closing_period"]);
    let multi = generate_off(&scope, "off-multi", &["multi_table_txn"]);
    let month = generate_off(&scope, "off-month", &["month_end_txn"]);
    let five = generate_off(
        &scope,
        "off-five",
        &[
            "cents",
            "fiscal_calendar",
            "closing_period",
            "multi_table_txn",
            "month_end_txn",
        ],
    );
    let names: Vec<String> = SMELLS.iter().copied().map(str::to_string).collect();
    let all = scope.join("off-all");
    let mut options = opts(Scale::Xs, 11, &all, &scope);
    options.smells = SmellSet::parse_off(&names).unwrap();
    generate(&options).expect("all off");
    verify_dataset(&all).expect("verify all off");

    let dd = "source-inputs/mysql-erp/tables/dd.csv";
    let mysql = "source-inputs/mysql-erp/ddl.sql";
    let postgres = "source-inputs/postgres-tms/ddl.sql";
    let calendar = "hidden-truth/calendar.json";
    let sk = "source-inputs/mysql-erp/tables/sk.csv";
    let txn = "source-inputs/workload/txn_log.csv";
    let on_dd = read(&on, dd);
    let off_dd = read(&cents, dd);
    assert!(on_dd.contains(",17550,"));
    assert!(!on_dd.contains(",175.50,"));
    assert!(off_dd.contains(",175.50,"));
    assert!(read(&cents, mysql).contains("decimal(20,2)"));
    assert!(read(&cents, postgres).contains("numeric(20,2)"));
    assert!(!read(&on, mysql).contains("decimal(20,2)"));
    assert!(read(&on, calendar).contains("\"fy2026_start\":\"2025-04-01\""));
    assert!(read(&fiscal, calendar).contains("\"fy2026_start\":\"2026-01-01\""));
    assert!(read(&on, calendar).contains("\"closing_lag_days\":5"));
    assert!(read(&closing, calendar).contains("\"closing_lag_days\":0"));
    assert_eq!(april_jzbz(&read(&on, sk)), "1");
    assert_eq!(april_jzbz(&read(&closing, sk)), "0");
    assert_eq!(rows(&on.join(txn)), 9_100);
    assert_eq!(rows(&multi.join(txn)), 3_100);
    assert!(read(&multi, txn).contains(",order\n"));
    assert!(!read(&multi, txn).contains(",ship\n"));
    assert_eq!(rows(&month.join(txn)), 8_100);
    assert!(!read(&month, txn).contains(",month_end\n"));
    assert_eq!(rows(&five.join(txn)), 2_100);
    assert!(read(&five, dd).contains(",175.50,"));
    assert_eq!(april_jzbz(&read(&five, sk)), "0");
    assert!(read(&five, calendar).contains("\"fy2026_start\":\"2026-01-01\""));
    assert!(read(&five, calendar).contains("\"closing_lag_days\":0"));

    for (name, needle) in [
        (
            "cents",
            "amount is not exact fixed-point yuan while cents is off",
        ),
        ("fiscal_calendar", "fiscal calendar document"),
        ("closing_period", "closing lag drift"),
        ("multi_table_txn", "row count txn_rows"),
        ("month_end_txn", "row count month_end"),
    ] {
        let copied = scope.join(format!("flip-{name}"));
        copy_tree(&on, &copied);
        let text = replace_once(
            &manifest(&copied),
            &format!("\"{name}\":true"),
            &format!("\"{name}\":false"),
        );
        reseal(&copied, &text);
        expect_contains(&copied, needle);
    }

    let anomaly = scope.join("anomaly-cents");
    copy_tree(&on, &anomaly);
    let rel = "hidden-truth/anomalies.json";
    let text = replace_once(
        &fs::read_to_string(anomaly.join(rel)).unwrap(),
        "{\"enabled\":true,\"smell\":\"cents\"}",
        "{\"enabled\":false,\"smell\":\"cents\"}",
    );
    fs::write(anomaly.join(rel), text).unwrap();
    reseal_content(&anomaly, rel);
    expect_contains(&anomaly, "anomaly flag drift on cents");

    for (rel, columns, needle) in [
        (
            "source-inputs/mysql-erp/tables/ys.csv",
            1,
            "duplicate primary key ysid",
        ),
        (
            "source-inputs/postgres-tms/tables/cl.csv",
            1,
            "duplicate primary key cph",
        ),
        (
            "source-inputs/postgres-tms/tables/xl.csv",
            1,
            "duplicate primary key xlbh",
        ),
        (
            "source-inputs/postgres-tms/tables/kc.csv",
            3,
            "duplicate primary key ckid,sku,yf",
        ),
    ] {
        let copied = scope.join(format!("dup-{}", rel.rsplit('/').next().unwrap()));
        copy_tree(&on, &copied);
        rewrite_row_key(&copied.join(rel), columns);
        reseal_content(&copied, rel);
        expect_contains(&copied, needle);
    }

    let dropped = scope.join("ddl-drop-pk");
    copy_tree(&on, &dropped);
    rewrite_once(
        &dropped,
        "source-inputs/mysql-erp/ddl.sql",
        "  PRIMARY KEY (`khid`)\n",
        "-- PRIMARY KEY (`khid`)\n",
    );
    expect_contains(&dropped, "primary key drift on kh");

    let narrow = scope.join("ddl-narrow");
    copy_tree(&on, &narrow);
    rewrite_first(
        &narrow,
        "source-inputs/mysql-erp/ddl.sql",
        "`khid` varchar(32)",
        "`khid` varchar(1)",
    );
    expect_contains(
        &narrow,
        "ddl type kh.khid is varchar(1), expected varchar(32)",
    );

    let catalog = scope.join("catalog-narrow");
    copy_tree(&on, &catalog);
    let rel = "source-inputs/mysql-erp/catalog.json";
    let text = fs::read_to_string(catalog.join(rel)).unwrap();
    let pos = text.find("\"sql\":\"varchar(32)\"").unwrap();
    assert!(text[..pos].contains("\"name\":\"khid\""));
    let updated = text.replacen("\"sql\":\"varchar(32)\"", "\"sql\":\"varchar(1)\"", 1);
    fs::write(catalog.join(rel), updated).unwrap();
    reseal_content(&catalog, rel);
    expect_contains(
        &catalog,
        "catalog type kh.khid is varchar(1), expected varchar(32)",
    );

    let injected = scope.join("ddl-select");
    copy_tree(&on, &injected);
    let rel = "source-inputs/mysql-erp/ddl.sql";
    let mut text = fs::read_to_string(injected.join(rel)).unwrap();
    text.push_str("SELECT 1;\n");
    fs::write(injected.join(rel), text).unwrap();
    reseal_content(&injected, rel);
    expect_contains(&injected, "ddl statement is not a create table");

    let shaped = scope.join("multi-shape");
    copy_tree(&multi, &shaped);
    force_shared_txn(&shaped.join(txn));
    reseal_content(&shaped, txn);
    expect_contains(
        &shaped,
        "multi-table shipment present while multi_table_txn is off",
    );

    let jzbz = scope.join("closing-jzbz");
    copy_tree(&closing, &jzbz);
    set_april_jzbz(&jzbz.join(sk), "1");
    reseal_content(&jzbz, sk);
    expect_contains(&jzbz, "april jzbz");

    tmp_scope_is_allowed();
}

fn generate_off(scope: &Path, name: &str, off: &[&str]) -> PathBuf {
    let output = scope.join(name);
    let mut options = opts(Scale::Xs, 11, &output, scope);
    let names: Vec<String> = off.iter().copied().map(str::to_string).collect();
    options.smells = SmellSet::parse_off(&names).unwrap();
    generate(&options).unwrap_or_else(|err| panic!("{name}: {err}"));
    verify_dataset(&output).unwrap_or_else(|err| panic!("verify {name}: {err}"));
    output
}

fn read(root: &Path, rel: &str) -> String {
    fs::read_to_string(root.join(rel)).unwrap_or_else(|err| panic!("{rel}: {err}"))
}

fn expect_contains(root: &Path, needle: &str) {
    let err = verify_dataset(root).unwrap_err();
    assert!(err.to_string().contains(needle), "{err} missing {needle}");
}

fn reseal_content(root: &Path, rel: &str) {
    let (len, digest) = hash_file(&root.join(rel)).unwrap();
    let text = manifest(root);
    let needle = format!("\"path\":\"{rel}\"");
    assert_eq!(text.matches(&needle).count(), 1, "{rel}");
    let path_at = text.find(&needle).unwrap();
    let obj_start = text[..path_at].rfind('{').unwrap();
    let obj_end = path_at + text[path_at..].find('}').unwrap();
    let mut window = text[obj_start..=obj_end].to_string();
    let sha = "\"sha256\":\"";
    let sha_at = window.find(sha).unwrap() + sha.len();
    window.replace_range(sha_at..sha_at + 64, &digest);
    let bytes = "\"bytes\":";
    let bytes_at = window.find(bytes).unwrap() + bytes.len();
    let bytes_end = bytes_at + window[bytes_at..].find([',', '}']).unwrap();
    window.replace_range(bytes_at..bytes_end, &len.to_string());
    let mut updated = text;
    updated.replace_range(obj_start..=obj_end, &window);
    let updated = set_tree(
        &updated,
        &tree_with_override(root, "no-such-path", "unused"),
    );
    reseal(root, &updated);
}

fn rewrite_once(root: &Path, rel: &str, from: &str, to: &str) {
    let text = replace_once(&fs::read_to_string(root.join(rel)).unwrap(), from, to);
    fs::write(root.join(rel), text).unwrap();
    reseal_content(root, rel);
}

fn rewrite_first(root: &Path, rel: &str, from: &str, to: &str) {
    let text = fs::read_to_string(root.join(rel)).unwrap();
    assert!(text.contains(from), "{from} missing from {rel}");
    fs::write(root.join(rel), text.replacen(from, to, 1)).unwrap();
    reseal_content(root, rel);
}

fn split_fields(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut quoted = false;
    for (index, byte) in line.bytes().enumerate() {
        if byte == b'"' {
            quoted = !quoted;
        } else if byte == b',' && !quoted {
            out.push(line[start..index].to_string());
            start = index + 1;
        }
    }
    out.push(line[start..].to_string());
    out
}

fn rewrite_row_key(path: &Path, columns: usize) {
    let text = fs::read_to_string(path).unwrap();
    let mut lines: Vec<String> = text.split_inclusive('\n').map(str::to_string).collect();
    let donor = split_fields(lines[2].trim_end_matches(['\n', '\r']));
    let mut row = split_fields(lines[1].trim_end_matches(['\n', '\r']));
    assert_eq!(donor.len(), row.len(), "{}", path.display());
    for index in 0..columns {
        row[index].clone_from(&donor[index]);
    }
    let newline = if lines[1].ends_with('\n') { "\n" } else { "" };
    lines[1] = format!("{}{newline}", row.join(","));
    fs::write(path, lines.concat()).unwrap();
}

fn april_jzbz(text: &str) -> String {
    let line = text
        .lines()
        .find(|line| line.starts_with("SA"))
        .expect("april receipt");
    let fields = split_fields(line);
    assert_eq!(fields[5], "2026-04-02");
    fields[6].clone()
}

fn set_april_jzbz(path: &Path, value: &str) {
    let text = fs::read_to_string(path).unwrap();
    let mut lines: Vec<String> = text.split_inclusive('\n').map(str::to_string).collect();
    let index = lines
        .iter()
        .position(|line| line.starts_with("SA"))
        .expect("april receipt");
    let mut fields = split_fields(lines[index].trim_end_matches(['\n', '\r']));
    assert_eq!(fields[5], "2026-04-02");
    fields[6] = value.to_string();
    let newline = if lines[index].ends_with('\n') {
        "\n"
    } else {
        ""
    };
    lines[index] = format!("{}{newline}", fields.join(","));
    fs::write(path, lines.concat()).unwrap();
}

fn force_shared_txn(path: &Path) {
    let text = fs::read_to_string(path).unwrap();
    let mut lines: Vec<String> = text.split_inclusive('\n').map(str::to_string).collect();
    let first = split_fields(lines[1].trim_end_matches(['\n', '\r']));
    let mut second = split_fields(lines[2].trim_end_matches(['\n', '\r']));
    second[1].clone_from(&first[1]);
    second[2] = "2".to_string();
    second[4] = "ys".to_string();
    let base = first[6].parse::<i64>().unwrap() - first[2].parse::<i64>().unwrap();
    second[6] = (base + 2).to_string();
    let newline = if lines[2].ends_with('\n') { "\n" } else { "" };
    lines[2] = format!("{}{newline}", second.join(","));
    fs::write(path, lines.concat()).unwrap();
}

fn tmp_scope_is_allowed() {
    let parent = PathBuf::from(format!("/tmp/oo-datagen-a028-tmp-{}", std::process::id()));
    let _ = fs::remove_dir_all(&parent);
    fs::create_dir(&parent).unwrap();
    let output = parent.join("xs");
    let result = generate(&opts(Scale::Xs, 11, &output, Path::new("/tmp")));
    if let Ok(report) = result {
        let verified = verify_dataset(&output).expect("verify tmp");
        assert_eq!(verified.tree_sha256, report.tree_sha256);
        fs::remove_dir_all(&parent).unwrap();
    } else {
        let _ = fs::remove_dir_all(&parent);
        panic!("{}", result.unwrap_err());
    }
}
